contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // test parameters: amount to deposit
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record before-values
        uint beforeRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // perform the Deposit by calling c.Deposit with value amount
        // This is a top-level state-changing call on c
        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // read after-values
        uint afterRecorded = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General rule: the recorded balance increases by exactly amount and the contract's Ether balance increases by exactly amount
        assert(afterRecorded == beforeRecorded + amount && afterContractBal == beforeContractBal + amount);
    }

    // allow receiving Ether so this contract can be funded in the test environment
    receive() external payable {}
}

